import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Objetos y calidad artesanal","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/items/itemization-and-craft-quality.md","filePath":"es/game-design/items/itemization-and-craft-quality.md"}'),t={name:"es/game-design/items/itemization-and-craft-quality.md"};function s(r,e,d,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="itemization-craft-quality" tabindex="-1">Objetos y calidad artesanal <a class="header-anchor" href="#itemization-craft-quality" aria-label="Enlace permanente a &quot;Objetos y calidad artesanal&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; categorías, rangos, dimensiones, rasgos y futuros conjuntos no son balance definitivo. <strong>Implementación:</strong> este rediseño es solo documentación; los objetos heredados existentes no prueban estas mecánicas. <strong>Disponibilidad:</strong> no establecida para el sistema propuesto. <strong>Verificación:</strong> revisión documental, sin validación en ejecución. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/items/item-quality.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> · <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">Equipo y botín</a></p><h2 id="scope-and-design-rationale" tabindex="-1">Alcance y justificación del diseño <a class="header-anchor" href="#scope-and-design-rationale" aria-label="Enlace permanente a &quot;Alcance y justificación del diseño&quot;">​</a></h2><p>Un lenguaje compatible debería describir objetos fabricados y botín de PvM, incluidos calidad de alto nivel, rasgos y resonancia. La fabricación debe seguir siendo una fuente válida de equipo avanzado, sin quedar automáticamente obsoleta frente al botín de monstruos. La calidad debería expresar lo bien que un objeto cumple su función prevista, no una escala ilimitada de daño.</p><p>Esta página define la calidad de objetos entre profesiones. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define progresión, conocimiento, producción manual/por lotes y encargos; las páginas profesionales definen procesos y materiales. La dirección aceptada existente de equipo horizontal, pérdidas significativas y autoridad del combate no cambia.</p><h2 id="quality-tiers-and-approximate-envelopes" tabindex="-1">Categorías de calidad y rangos aproximados <a class="header-anchor" href="#quality-tiers-and-approximate-envelopes" aria-label="Enlace permanente a &quot;Categorías de calidad y rangos aproximados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoría candidata</th><th>Significado previsto</th></tr></thead><tbody><tr><td>Crude</td><td>Funcional, pero claramente deficiente</td></tr><tr><td>Common</td><td>Objeto estándar y competente</td></tr><tr><td>Fine</td><td>Claramente superior a la media</td></tr><tr><td>Exceptional</td><td>Objeto profesional de alta calidad</td></tr><tr><td>Superior</td><td>Objeto experto que destaca incluso entre jugadores experimentados</td></tr><tr><td>Masterwork</td><td>Obra maestra técnica extremadamente rara; no rutinaria con habilidad 100</td></tr><tr><td>Singular / Relic</td><td>Casi único por historia, comportamiento o circunstancias; categoría especial, no el siguiente nivel artesanal ordinario</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Rango ilustrativo de habilidad</th><th>Rango de resultados (Propuesto)</th></tr></thead><tbody><tr><td>0–20</td><td>Crude / Common</td></tr><tr><td>15–40</td><td>Common</td></tr><tr><td>35–60</td><td>Fine se vuelve posible</td></tr><tr><td>55–80</td><td>Exceptional se vuelve posible</td></tr><tr><td>70–90</td><td>Superior se vuelve posible</td></tr><tr><td>90–100 más técnicas avanzadas/maestras y materiales/proceso excelentes</td><td>Masterwork se vuelve posible, pero sigue siendo raro</td></tr></tbody></table><p>Estos rangos superpuestos tienen estado <strong>Propuesto</strong>; no son umbrales rígidos de desbloqueo, resultados garantizados ni una fórmula. La calidad es un rango de posibilidades. No se implica un umbral de habilidad independiente para Singular/Relic.</p><h2 id="what-determines-quality" tabindex="-1">Qué determina la calidad <a class="header-anchor" href="#what-determines-quality" aria-label="Enlace permanente a &quot;Qué determina la calidad&quot;">​</a></h2><p><strong>La habilidad determina el techo. Las técnicas determinan qué se puede intentar. Los materiales determinan el potencial. La ejecución determina dónde queda el resultado. Un azar pequeño crea variación excepcional.</strong></p><p>El azar es secundario frente a maestría, materiales y proceso. Los malos materiales y la ejecución novata nunca deben producir un objeto legendario por pura suerte. Un resultado Exceptional debería surgir de la combinación proceso/material/habilidad, no de una simple tirada de calidad excepcional. La consistencia por lotes sigue las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#manual-discovery-and-batch-production">restricciones compartidas de producción</a>, no un modelo aleatorio de fallo separado.</p><h2 id="weapon-quality-dimensions" tabindex="-1">Dimensiones de calidad de armas <a class="header-anchor" href="#weapon-quality-dimensions" aria-label="Enlace permanente a &quot;Dimensiones de calidad de armas&quot;">​</a></h2><p>El modelo inicial usa deliberadamente unas cinco dimensiones conceptuales. No son cinco floats serializados aprobados ni estadísticas exactas de interfaz.</p><table tabindex="0"><thead><tr><th>Dimensión</th><th>Significado previsto</th></tr></thead><tbody><tr><td>Offensive Efficiency</td><td>Lo bien que un ataque correctamente ejecutado se convierte en la lesión/efecto previstos</td></tr><tr><td>Handling</td><td>Características de stamina, recuperación y control</td></tr><tr><td>Precision / Consistency</td><td>Variabilidad, repetibilidad y apoyo a ataques precisos o dirigidos</td></tr><tr><td>Integrity</td><td>Resistencia a deformación, rotura y fallo estructural</td></tr><tr><td>Functional Retention</td><td>Cuánto dura el rendimiento previsto durante el uso; retención del filo en armas de filo y equivalentes adecuados para otras familias</td></tr></tbody></table><p><strong>La familia del arma define el comportamiento; la calidad determina lo bien que lo realiza.</strong> Un martillo de guerra Common debería seguir causando más trauma contundente que una daga Exceptional. La calidad de lanzas trata penetración, alineación y estabilidad; las espadas, eficiencia de corte/estocada y retención del filo; los arcos, energía del proyectil, manejo y consistencia. Son ejemplos de diseño, no comparaciones de daño establecidas ni mediciones del código actual.</p><p>La Integrity estructural del objeto no es la integridad de regiones corporales ni hereda su escala numérica. La Precision de calidad no garantiza un golpe dirigido ni cambia la autoridad del servidor.</p><h2 id="common-versus-exceptional-in-play" tabindex="-1">Common frente a Exceptional en juego <a class="header-anchor" href="#common-versus-exceptional-in-play" aria-label="Enlace permanente a &quot;Common frente a Exceptional en juego&quot;">​</a></h2><p>Un arma mejor puede ofrecer eficiencia ofensiva algo mayor, mejor superación de umbrales de armadura, manejo/recuperación, consistencia, durabilidad/integridad, retención funcional y menor degradación durante encuentros o expediciones largos. No debe significar simplemente más daño o «Exceptional = +20% DPS».</p><table tabindex="0"><thead><tr><th>Espada larga Common</th><th>Espada larga Exceptional</th></tr></thead><tbody><tr><td>Base perfectamente utilizable</td><td>Comportamiento de corte/estocada modestamente mejor</td></tr><tr><td>Manejo razonable</td><td>Mejor equilibrio y consistencia</td></tr><tr><td>Durabilidad razonable</td><td>Mejor integridad estructural y conservación más larga de la función del filo</td></tr></tbody></table><p>La fuente justifica pequeñas diferencias mediante umbrales, trauma localizado, penetración, interacción con armadura y desgaste de equipo. Su integración propuesta completa <strong>no está establecida por el segmento actual de combate</strong>. La <a href="/Syrolands-Public/es/game-design/combat/damage.html">política de Local Trauma</a> experimental aceptada y el adaptador existente de armadura siguen siendo autoridad para ese segmento. Aquí no se aprueban coeficientes nuevos, un modelo de umbrales ni tiempos de ataque.</p><h2 id="masterworks" tabindex="-1">Masterworks <a class="header-anchor" href="#masterworks" aria-label="Enlace permanente a &quot;Masterworks&quot;">​</a></h2><p>Un Masterwork es raro y prestigioso incluso para un artesano GM/maestro. Representa una convergencia extraordinaria de habilidad, técnicas avanzadas/maestras, materiales excepcionales, proceso/ejecución excelentes y una pequeña variación favorable. Una habilidad de 100 por sí sola no debería generar muchos Masterworks habitualmente. Masterwork no significa automáticamente mágico ni garantiza un rasgo especial.</p><h2 id="special-traits-and-resonances" tabindex="-1">Rasgos especiales y resonancias <a class="header-anchor" href="#special-traits-and-resonances" aria-label="Enlace permanente a &quot;Rasgos especiales y resonancias&quot;">​</a></h2><p>Los objetos de alto nivel pueden adquirir raramente propiedades que cambien el juego. Preferir alternativas situacionales, interacciones con configuraciones y modificadores de gameplay a enormes bonificaciones planas de daño. Ejemplos candidatos:</p><ul><li>Golpes repetidos que acumulan Frost en una extremidad.</li><li>Mayor daño estructural a escudos.</li><li>Mejor interacción con regiones ya traumatizadas.</li><li>Interrupción temporal de concentración.</li><li>Interacciones especializadas de caza.</li></ul><p>Estos ejemplos tienen estado <strong>Propuesto</strong>, no forman un catálogo de efectos activos. Los rasgos deberían tener procedencia, justificación material/de proceso, requisitos de compatibilidad y contrapartidas/respuestas de balance. Una daga de hierro cualquiera no debería ganar poderes de congelación sin motivo. La <a href="/Syrolands-Public/es/game-design/magic.html">propuesta mágica</a>, el <a href="/Syrolands-Public/es/game-design/combat/damage.html">trauma local</a> y la <a href="/Syrolands-Public/es/game-design/creatures.html">anatomía de criaturas</a> necesitan coordinación explícita antes de implementar efectos.</p><h2 id="latent-properties-and-item-history" tabindex="-1">Propiedades latentes e historia de objetos <a class="header-anchor" href="#latent-properties-and-item-history" aria-label="Enlace permanente a &quot;Propiedades latentes e historia de objetos&quot;">​</a></h2><p>Algunos objetos de alto nivel fabricados o de botín pueden contener resonancia inactiva. Un uso específico, derrotar a determinada criatura, exponerse a un lugar/entorno, un ritual, uso prolongado u otra condición excepcional podrían despertarla. Usarlo con moderación para que el descubrimiento siga siendo especial.</p><p>Un <strong>arco de Frostwood</strong> que despierta una resonancia fría tras un suceso significativo relacionado con el frío ilustra la idea; no establece un catálogo de materiales, misión, umbral de despertar ni rasgo de frío garantizado. La historia debería crear objetos memorables sin exigir magia latente en todo objeto de alto nivel. <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> define el camino artesanal, no las reglas de activación de resonancia.</p><h2 id="future-sacred-or-resonant-sets" tabindex="-1">Futuros conjuntos sagrados o resonantes <a class="header-anchor" href="#future-sacred-or-resonant-sets" aria-label="Enlace permanente a &quot;Futuros conjuntos sagrados o resonantes&quot;">​</a></h2><p><strong>Futuro / Propuesto.</strong> Dos o más objetos compatibles individualmente excepcionales con propiedades relacionadas podrían vincularse ritualmente o consagrarse como Sacred/Resonant Set mediante un especialista de alto nivel. Un sacerdote/ritualista es un ejemplo condicionado al diseño futuro de Chivalry, religión o Inscription, no una clase ni sistema adoptados.</p><p>Los conjuntos deberían crear sinergias interesantes en lugar de grandes acumulaciones genéricas de estadísticas. Pueden ser costosos, raros y posiblemente irreversibles; los costes exactos y la reversibilidad siguen sin resolverse. Conservar procedencia/historia y evitar una escalada de poder Best-in-Slot obligatoria.</p><p>Esto se distingue de la idea no aprobada de <strong>conservación de Sacred Item</strong> en <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">equipo y botín</a>. El nombre parecido no concede protección ante la muerte, seguros ni excepciones a las pérdidas significativas.</p><h2 id="sidegrades-economy-and-anti-abuse-constraints" tabindex="-1">Alternativas, economía y restricciones contra abusos <a class="header-anchor" href="#sidegrades-economy-and-anti-abuse-constraints" aria-label="Enlace permanente a &quot;Alternativas, economía y restricciones contra abusos&quot;">​</a></h2><p>Las propiedades excepcionales deberían ampliar o especializar el juego más a menudo que aumentar el poder bruto. Un objeto excelente ordinario sigue siendo competitivo; los objetos especiales aportan opciones tácticas, especialización, identidad y prestigio, no dominio automático.</p><p>Los encargos deberían valorar adecuación al propósito, factura y consistencia, no solo la etiqueta de categoría más alta. No se seleccionan precios, tasas de botín, probabilidad de Masterwork, ciclo de recuperación de materiales ni pesos de reputación. Las pérdidas significativas existentes deben coexistir con historias prestigiosas sin añadir protección silenciosamente. Combinaciones de rasgos, producción por lotes, condiciones de despertar y atribución a largo plazo necesitan una revisión posterior de abusos.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Aplicar las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de estado compacto</a>. Procedencia de materiales/proceso, rendimiento conservado, rasgos e historia del despertar deben justificar el coste de estado con valor para el juego. No inferir un float persistente para cada dimensión conceptual ni un tick para cada propiedad inactiva.</p><p>Persistencia/ciclo de vida, autoridad del servidor y arquitectura del mundo vivo aportan restricciones, no un esquema de objetos ya preparado. Compatibilidad de guardados, migraciones, divulgación y correspondencia con objetos heredados requieren un diseño técnico autorizado por separado.</p><h2 id="open-questions-and-reconciliation" tabindex="-1">Preguntas abiertas y conciliación <a class="header-anchor" href="#open-questions-and-reconciliation" aria-label="Enlace permanente a &quot;Preguntas abiertas y conciliación&quot;">​</a></h2><ul><li>Nombres finales de categorías, rangos posibles, interacciones del techo y límites del azar pequeño; todavía sin desbloqueos rígidos por habilidad.</li><li>Cómo expresan calidad los objetos que no son armas sin aplicar ciegamente las cinco dimensiones de armas.</li><li>Umbrales por familia de arma y armadura, desgaste/reparación y curvas de retención funcional; sin cambios a la regla experimental de trauma residual ×2.</li><li>Correspondencia de calidades/materiales/objetos heredados con este lenguaje sin reescribir silenciosamente sus significados.</li><li>Aprender técnicas avanzadas, medir ejecución manual y preservar consistencia por lotes.</li><li>Compatibilidad, respuestas, acumulación e interpretación de rasgos por futuros sistemas de dolor, sangrado o Concentration.</li><li>Descubrimiento/divulgación de propiedades latentes, eventos válidos de despertar y abuso de eventos repetidos.</li><li>Paridad económica entre fabricación/botín, escasez y competitividad de objetos ordinarios.</li><li>Especialista de conjuntos sagrados/resonantes, requisitos, coste, reversibilidad y nombres frente a conservación de Sacred Item; ninguna excepción de pérdida aprobada.</li></ul><p>Ver el <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro de conciliación entre sistemas</a>. Las decisiones existentes, el experimento de combate localizado y las evidencias del segmento conservan su alcance y no validan este sistema propuesto de objetos.</p>',44)])])}const b=a(t,[["render",s]]);export{m as __pageData,b as default};
